/**
 * KS-871 — verifies the audit middleware records the ORIGINAL request path
 * (captured at entry), not the Express-trimmed remainder seen after routing.
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import express from 'express';
import http from 'node:http';
import type { AddressInfo } from 'node:net';
import { createAuditMiddleware } from '../middleware/audit';

const deps = {
  query: async (_sql: string, params: unknown[]) => {
    capturedParams = [...params];
    return { rows: [] };
  },
  isDbAvailable: () => true,
  log: () => {},
};

let capturedParams: unknown[] | null = null;

beforeEach(() => {
  capturedParams = null;
});

async function drive(method: string, path: string): Promise<number> {
  const app = express();
  app.use(express.json());

  // Refused erasure gate — answers 403 WITHOUT calling next(). This simulates
  // an earlier `router.use(prefix, handler)` gate that has already answered,
  // which is exactly when req.path gets trimmed by Express before finish fires.
  const gdprRouter = express.Router();
  gdprRouter.delete('/erasures/*', (_req, res) => {
    res.status(403).json({ error: 'forbidden' });
  });

  app.use(createAuditMiddleware(deps));
  app.use('/api/gdpr', gdprRouter);

  await new Promise<void>((resolve) => {
    server = app.listen(0, '127.0.0.1', resolve);
  });
  port = (server.address() as AddressInfo).port;

  try {
    const status = await new Promise<number>((resolve) => {
      const req = http.request(
        { host: '127.0.0.1', port, path, method },
        (res) => { res.resume(); resolve(res.statusCode ?? 0); },
      );
      req.on('error', () => resolve(-1));
      req.end();
    });
    return status;
  } finally {
    await new Promise<void>((r) => server.close(r));
  }
}

describe('KS-871 — audit log captures original request path at entry', () => {
  it('🔴 KS-871 — details.path is the original request path, not the trimmed remainder', async () => {
    const status = await drive('DELETE', '/api/gdpr/erasures/abc');
    expect(status).toBe(403);
    if (!capturedParams || capturedParams.length < 9) throw new Error('no capture');
    const detailsStr = String(capturedParams[8]);
    const details = JSON.parse(detailsStr);
    expect(details.path).toBe('/api/gdpr/erasures/abc');
  });

  it('🔴 KS-871 — action/resource are derived from the original path', async () => {
    const status = await drive('DELETE', '/api/gdpr/erasures/abc');
    expect(status).toBe(403);
    if (!capturedParams || capturedParams.length < 5) throw new Error('no capture');
    const action = String(capturedParams[3]);
    const resourceType = String(capturedParams[4]);
    // With the fix, segments come from /api/gdpr/erasures/abc → section='gdpr', subResource='erasures'.
    // The deriveAction mapping should produce an action containing 'gdpr' and a non-'unknown' resource type.
    expect(action).toMatch(/gdpr/);
    expect(resourceType).not.toBe('unknown');
  });

  it('KS-871 control — an ordinary POST /api/documents still audits its own path', async () => {
    const app = express();
